const oAuthRequestClaim = `-- name: OAuthRequestClaim :one
UPDATE oauth_requests
SET user_id = $1
WHERE id_hash = $2 AND expires_at > $3::timestamptz
  AND (user_id IS NULL OR user_id = $1)
RETURNING id_hash, app_id, user_id, redirect_uri, scopes, state, code_challenge, code_challenge_method, created_at, expires_at
`

type OAuthRequestClaimParams struct {
	UserID pgtype.UUID
	IDHash []byte
	Now    time.Time
}

// Returns an unexpired pending request for user_id, binding it to that user
// if nobody has opened it yet. No row: unknown, expired or another user's.
func (q *Queries) OAuthRequestClaim(ctx context.Context, arg OAuthRequestClaimParams) (OauthRequest, error) {
	row := q.db.QueryRow(ctx, oAuthRequestClaim, arg.UserID, arg.IDHash, arg.Now)
	var i OauthRequest
	err := row.Scan(
		&i.IDHash,
		&i.AppID,
		&i.UserID,
		&i.RedirectUri,
		&i.Scopes,
		&i.State,
		&i.CodeChallenge,
		&i.CodeChallengeMethod,
		&i.CreatedAt,
		&i.ExpiresAt,
	)
	return i, err
}

const oAuthRequestConsume = `-- name: OAuthRequestConsume :one
DELETE FROM oauth_requests
WHERE id_hash = $1 AND expires_at > $2::timestamptz
  AND (user_id IS NULL OR user_id = $3)
RETURNING id_hash, app_id, user_id, redirect_uri, scopes, state, code_challenge, code_challenge_method, created_at, expires_at
`

type OAuthRequestConsumeParams struct {
	IDHash []byte
	Now    time.Time
	UserID pgtype.UUID
}

// Removes and returns a pending request, as OAuthRequestClaim matches it.
func (q *Queries) OAuthRequestConsume(ctx context.Context, arg OAuthRequestConsumeParams) (OauthRequest, error) {
	row := q.db.QueryRow(ctx, oAuthRequestConsume, arg.IDHash, arg.Now, arg.UserID)
	var i OauthRequest
	err := row.Scan(
		&i.IDHash,
		&i.AppID,
		&i.UserID,
		&i.RedirectUri,
		&i.Scopes,
		&i.State,
		&i.CodeChallenge,
		&i.CodeChallengeMethod,
		&i.CreatedAt,
		&i.ExpiresAt,
	)
	return i, err
}

