const publicPrograms = `-- name: PublicPrograms :many
SELECT slug, name, homepage_url FROM oauth_apps
WHERE public AND deleted_at IS NULL
ORDER BY lower(name), slug
`

type PublicProgramsRow struct {
	Slug        string
	Name        string
	HomepageUrl string
}

func (q *Queries) PublicPrograms(ctx context.Context) ([]PublicProgramsRow, error) {
	rows, err := q.db.Query(ctx, publicPrograms)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []PublicProgramsRow{}
	for rows.Next() {
		var i PublicProgramsRow
		if err := rows.Scan(&i.Slug, &i.Name, &i.HomepageUrl); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
